     9	import br.com.pousadamarealta.repository.RoomRepository;
    10	import br.com.pousadamarealta.service.ReservationService;
    11	import io.javalin.Javalin;
    12	import io.javalin.http.HttpStatus;
    13	
    14	import java.math.BigDecimal;
    15	import java.time.LocalDate;
    16	import java.time.format.DateTimeParseException;
    17	
    18	public class ReservationsController {
    19	    private final ReservationService reservationService;
    20	    private final RoomRepository roomRepository;
    21	
    22	    public ReservationsController(ReservationService reservationService, RoomRepository roomRepository) {
    23	        this.reservationService = reservationService;
    24	        this.roomRepository = roomRepository;
    25	    }
    26	
    27	    public void register(Javalin app) {
    28	        app.post("/reservations", ctx -> {
    29	            try {
    30	                CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
    31	
    32	                if (request.roomNumber() == null || request.guestName() == null ||
    33	                    request.guestEmail() == null || request.guestCpf() == null ||
    34	                    request.checkIn() == null || request.checkOut() == null ||
    35	                    request.guests() == null || request.ratePlan() == null) {
    36	                    ctx.status(HttpStatus.BAD_REQUEST);
    37	                    ctx.json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
    38	                    return;
    39	                }
    40	
    41	                LocalDate checkIn = LocalDate.parse(request.checkIn());
    42	                LocalDate checkOut = LocalDate.parse(request.checkOut());
    43	
    44	                if (!checkOut.isAfter(checkIn)) {
    45	                    ctx.status(HttpStatus.BAD_REQUEST);
    46	                    ctx.json(new ErrorResponse("INVALID_REQUEST", "Check-out must be after check-in"));
    47	                    return;
    48	                }
    49	
    50	                Reservation reservation = reservationService.create(
    51	                    request.roomNumber(),
    52	                    request.guestName(),
    53	                    request.guestEmail(),
    54	                    request.guestCpf(),
    55	                    checkIn,
    56	                    checkOut,
    57	                    request.guests(),
    58	                    request.ratePlan()
    59	                );
    60	
    61	                Room room = roomRepository.findByNumber(reservation.getRoomNumber());
    62	                ctx.status(HttpStatus.CREATED);
    63	                ctx.json(ReservationDTO.from(reservation, room));
    64	
    65	            } catch (DateTimeParseException e) {
    66	                ctx.status(HttpStatus.BAD_REQUEST);
    67	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
    68	            } catch (IllegalArgumentException e) {
    69	                ctx.status(HttpStatus.BAD_REQUEST);
    70	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid rate plan"));
    71	            }
    72	        });
    73	
    74	        app.get("/reservations/{id}", ctx -> {
    75	            Long id = ctx.pathParamAsClass("id", Long.class).get();
    76	            Reservation reservation = reservationService.findById(id);
    77	            Room room = roomRepository.findByNumber(reservation.getRoomNumber());
    78	            ctx.json(ReservationDTO.from(reservation, room));
    79	        });
    80	
    81	        app.post("/reservations/{id}/confirmation", ctx -> {
    82	            Long id = ctx.pathParamAsClass("id", Long.class).get();
    83	            Reservation reservation = reservationService.confirm(id);
    84	            Room room = roomRepository.findByNumber(reservation.getRoomNumber());
    85	            ctx.json(ReservationDTO.from(reservation, room));
    86	        });
    87	
    88	        app.post("/reservations/{id}/cancellation", ctx -> {
    89	            Long id = ctx.pathParamAsClass("id", Long.class).get();
    90	            Reservation reservation = reservationService.cancel(id);
    91	            Room room = roomRepository.findByNumber(reservation.getRoomNumber());
    92	            ctx.json(ReservationDTO.from(reservation, room));
    93	        });
    94	
    95	        app.post("/reservations/{id}/check-in", ctx -> {
    96	            Long id = ctx.pathParamAsClass("id", Long.class).get();
    97	            Reservation reservation = reservationService.checkIn(id);
    98	            Room room = roomRepository.findByNumber(reservation.getRoomNumber());
    99	            ctx.json(ReservationDTO.from(reservation, room));
   100	        });
   101	
   102	        app.post("/reservations/{id}/check-out", ctx -> {
   103	            Long id = ctx.pathParamAsClass("id", Long.class).get();
   104	            Reservation reservation = reservationService.checkOut(id);
   105	            String document = reservationService.getDocument(id);
   106	
   107	            Room room = roomRepository.findByNumber(reservation.getRoomNumber());
   108	            BigDecimal subtotal = reservation.calculateSubtotal(room.getNightlyRate());
   109	            BigDecimal discount = reservation.calculateDiscount(subtotal);
   110	            BigDecimal total = subtotal.subtract(discount);
   111	
   112	            ctx.json(DocumentDTO.from(reservation, room.getType(), subtotal, discount, total));
   113	        });
   114	
   115	        app.get("/reservations/{id}/document", ctx -> {
   116	            Long id = ctx.pathParamAsClass("id", Long.class).get();
   117	            Reservation reservation = reservationService.findById(id);
   118	
   119	            if (!reservation.isPaid()) {
   120	                ctx.status(HttpStatus.CONFLICT);
   121	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Document is only available for paid reservations"));
   122	                return;
   123	            }
   124	
   125	            Room room = roomRepository.findByNumber(reservation.getRoomNumber());
   126	            BigDecimal subtotal = reservation.calculateSubtotal(room.getNightlyRate());
   127	            BigDecimal discount = reservation.calculateDiscount(subtotal);
   128	            BigDecimal total = subtotal.subtract(discount);
   129	
   130	            ctx.json(DocumentDTO.from(reservation, room.getType(), subtotal, discount, total));
   131	        });
   132	    }
   133	}
