    25	    public String generateOccupancyReport(LocalDate date) {
    26	        List<Room> allRooms = roomRepository.findAll();
    27	        List<Reservation> occupiedReservations = reservationRepository.findOccupiedRoomsOnDate(date);
    28	
    29	        StringBuilder csv = new StringBuilder();
    30	        csv.append("room,type,reservation,check_in,check_out\n");
    31	
    32	        for (Reservation reservation : occupiedReservations) {
    33	            Room room = roomRepository.findByNumber(reservation.getRoomNumber());
    34	            csv.append(reservation.getRoomNumber()).append(",");
    35	            csv.append(room.getType().name()).append(",");
    36	            csv.append(reservation.getId()).append(",");
    37	            csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
    38	            csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append("\n");
    39	        }
    40	
    41	        csv.append("total,").append(occupiedReservations.size()).append("/").append(allRooms.size());
    42	
    43	        return csv.toString();
    44	    }
    45	
    46	    public String generateRevenueReport(YearMonth month) {
    47	        List<Reservation> reservations = reservationRepository.findReservationsStartingInMonth(month);
    48	
    49	        StringBuilder csv = new StringBuilder();
    50	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    51	
    52	        BigDecimal totalRevenue = BigDecimal.ZERO;
    53	
    54	        for (Reservation reservation : reservations) {
    55	            BigDecimal revenue = reservation.getAmountPaid();
    56	            if (reservation.getRefund() != null) {
    57	                revenue = revenue.subtract(reservation.getRefund());
    58	            }
    59	
    60	            csv.append(reservation.getId()).append(",");
    61	            csv.append(reservation.getRoomNumber()).append(",");
    62	            csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
    63	            csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append(",");
    64	            csv.append(reservation.getStatus().name()).append(",");
    65	            csv.append(String.format("%.2f", revenue)).append("\n");
    66	
    67	            totalRevenue = totalRevenue.add(revenue);
    68	        }
    69	
    70	        csv.append("total,").append(String.format("%.2f", totalRevenue));
    71	
    72	        return csv.toString();
    73	    }
