    15	public class ReservationService {
    16	    private final ReservationRepository reservationRepository;
    17	    private final RoomRepository roomRepository;
    18	    private final EventPublisher eventPublisher;
    19	
    20	    public ReservationService(ReservationRepository reservationRepository,
    21	                            RoomRepository roomRepository,
    22	                            EventPublisher eventPublisher) {
    23	        this.reservationRepository = reservationRepository;
    24	        this.roomRepository = roomRepository;
    25	        this.eventPublisher = eventPublisher;
    26	    }
    27	
    28	    public Reservation create(String roomNumber, String guestName, String guestEmail, String guestCpf,
    29	                             LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan) {
    30	
    31	        Room room = roomRepository.findByNumber(roomNumber);
    32	        if (room == null) {
    33	            throw new RoomNotFoundException();
    34	        }
    35	
    36	        if (guests < 1) {
    37	            throw new InvalidRequestException("Number of guests must be at least 1");
    38	        }
    39	
    40	        if (guests > room.getCapacity()) {
    41	            throw new CapacityExceededException();
    42	        }
    43	
    44	        if (reservationRepository.hasConflict(roomNumber, checkIn, checkOut, null)) {
    45	            throw new RoomUnavailableException();
    46	        }
    47	
    48	        Reservation reservation = new Reservation(
    49	            roomNumber, guestName, guestEmail, guestCpf,
    50	            checkIn, checkOut, guests,
    51	            br.com.pousadamarealta.domain.RatePlan.valueOf(ratePlan)
    52	        );
    53	
    54	        return reservationRepository.save(reservation);
    55	    }
    56	
    57	    public Reservation findById(Long id) {
    58	        Reservation reservation = reservationRepository.findById(id);
    59	        if (reservation == null) {
    60	            throw new ReservationNotFoundException();
    61	        }
    62	        return reservation;
    63	    }
    64	
    65	    public Reservation confirm(Long id) {
    66	        Reservation reservation = findById(id);
    67	
    68	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    69	            throw new OperationNotAllowedException();
    70	        }
    71	
    72	        Room room = roomRepository.findByNumber(reservation.getRoomNumber());
    73	        BigDecimal total = reservation.calculateTotal(room.getNightlyRate());
    74	
    75	        reservation.confirm();
    76	        reservation.setAmountPaid(total);
    77	        reservationRepository.save(reservation);
    78	
    79	        eventPublisher.publish(new ReservationConfirmedEvent(reservation, total));
    80	
    81	        return reservation;
    82	    }
    83	
    84	    public Reservation cancel(Long id) {
    85	        Reservation reservation = findById(id);
    86	
    87	        if (reservation.getStatus() != ReservationStatus.PENDING &&
    88	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
    89	            throw new OperationNotAllowedException();
    90	        }
    91	
    92	        boolean wasConfirmed = reservation.getStatus() == ReservationStatus.CONFIRMED;
    93	        BigDecimal refundAmount = reservation.calculateRefund();
    94	
    95	        reservation.cancel();
    96	        reservation.setRefund(refundAmount);
    97	        reservationRepository.save(reservation);
    98	
    99	        eventPublisher.publish(new ReservationCancelledEvent(reservation, wasConfirmed, refundAmount));
   100	
   101	        return reservation;
   102	    }
   103	
   104	    public Reservation checkIn(Long id) {
   105	        Reservation reservation = findById(id);
   106	
   107	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
   108	            throw new OperationNotAllowedException();
   109	        }
   110	
   111	        reservation.checkIn();
   112	        return reservationRepository.save(reservation);
   113	    }
   114	
   115	    public Reservation checkOut(Long id) {
   116	        Reservation reservation = findById(id);
   117	
   118	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   119	            throw new OperationNotAllowedException();
   120	        }
   121	
   122	        reservation.checkOut();
   123	        return reservationRepository.save(reservation);
   124	    }
   125	
   126	    public String getDocument(Long id) {
   127	        Reservation reservation = findById(id);
   128	
   129	        if (!reservation.isPaid()) {
   130	            throw new OperationNotAllowedException();
   131	        }
