     9	import br.com.pousadamarealta.repository.MessageRepository;
    10	
    11	import java.math.BigDecimal;
    12	
    13	public class FinanceNotifier implements ReservationEventListener {
    14	    private static final String FINANCE_EMAIL = "financeiro@pousadamarealta.com.br";
    15	    private final MessageRepository messageRepository;
    16	
    17	    public FinanceNotifier(MessageRepository messageRepository) {
    18	        this.messageRepository = messageRepository;
    19	    }
    20	
    21	    @Override
    22	    public void onEvent(ReservationEvent event) {
    23	        if (event instanceof ReservationConfirmedEvent confirmed) {
    24	            handleConfirmed(confirmed);
    25	        } else if (event instanceof ReservationCancelledEvent cancelled) {
    26	            handleCancelled(cancelled);
    27	        }
    28	    }
    29	
    30	    private void handleConfirmed(ReservationConfirmedEvent event) {
    31	        Reservation reservation = event.getReservation();
    32	        String subject = "Pagamento recebido - reserva " + reservation.getId();
    33	        String body = "Valor: " + reservation.formatMoney(event.getAmountPaid());
    34	
    35	        Message message = new Message("EMAIL", FINANCE_EMAIL, subject, body);
    36	        messageRepository.save(message);
    37	    }
    38	
    39	    private void handleCancelled(ReservationCancelledEvent event) {
    40	        if (!event.wasConfirmed()) {
    41	            return;
    42	        }
    43	
    44	        if (event.getRefundAmount().compareTo(BigDecimal.ZERO) == 0) {
    45	            return;
    46	        }
    47	
    48	        Reservation reservation = event.getReservation();
    49	        String subject = "Reembolso - reserva " + reservation.getId();
    50	        String body = "Valor: " + reservation.formatMoney(event.getRefundAmount());
    51	
    52	        Message message = new Message("EMAIL", FINANCE_EMAIL, subject, body);
    53	        messageRepository.save(message);
    54	    }
