    26	
    27	    private void createTables(Connection conn) throws SQLException {
    28	        boolean isH2 = conn.getMetaData().getDatabaseProductName().contains("H2");
    29	        String idColumn = isH2 ? "BIGINT GENERATED BY DEFAULT AS IDENTITY" : "BIGSERIAL";
    30	
    31	        String createRooms = """
    32	            CREATE TABLE IF NOT EXISTS rooms (
    33	                number VARCHAR(10) PRIMARY KEY,
    34	                type VARCHAR(20) NOT NULL
    35	            )
    36	            """;
    37	
    38	        String createReservations = String.format("""
    39	            CREATE TABLE IF NOT EXISTS reservations (
    40	                id %s PRIMARY KEY,
    41	                room_number VARCHAR(10) NOT NULL,
    42	                guest_name VARCHAR(255) NOT NULL,
    43	                guest_email VARCHAR(255) NOT NULL,
    44	                guest_cpf VARCHAR(11) NOT NULL,
    45	                check_in DATE NOT NULL,
    46	                check_out DATE NOT NULL,
    47	                guests INTEGER NOT NULL,
    48	                rate_plan VARCHAR(20) NOT NULL,
    49	                status VARCHAR(20) NOT NULL,
    50	                amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
    51	                refund DECIMAL(10, 2),
    52	                FOREIGN KEY (room_number) REFERENCES rooms(number)
    53	            )
    54	            """, idColumn);
    55	
    56	        String createMessages = String.format("""
    57	            CREATE TABLE IF NOT EXISTS messages (
    58	                id %s PRIMARY KEY,
    59	                channel VARCHAR(50) NOT NULL,
    60	                destination VARCHAR(255) NOT NULL,
    61	                subject VARCHAR(500) NOT NULL,
    62	                body TEXT NOT NULL
    63	            )
    64	            """, idColumn);
    65	
    66	        conn.createStatement().execute(createRooms);
    67	        conn.createStatement().execute(createReservations);
