    71	    private void insertInitialRooms(Connection conn) throws SQLException {
    72	        String checkRooms = "SELECT COUNT(*) FROM rooms";
    73	        var rs = conn.createStatement().executeQuery(checkRooms);
    74	        rs.next();
    75	        if (rs.getInt(1) > 0) {
    76	            return;
    77	        }
    78	
    79	        String insertRoom = "INSERT INTO rooms (number, type) VALUES (?, ?)";
    80	        var stmt = conn.prepareStatement(insertRoom);
    81	
    82	        String[][] rooms = {
