  9	public class Reservation {
 10	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 11	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
 12	    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN);
