 62	    public BigDecimal calculateNightPrice(LocalDate night, BigDecimal baseRate) {
 63	        BigDecimal price = baseRate;
 64	        if (isHighSeason(night)) {
 65	            price = price.multiply(HIGH_SEASON_MULTIPLIER);
 66	        }
 67	        return price.setScale(2, RoundingMode.HALF_EVEN);
 68	    }
