168	    public String generateReceipt(RoomType roomType, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
169	        StringBuilder receipt = new StringBuilder();
170	        receipt.append("Comprovante de reserva nº ").append(id).append("\n");
