172	        receipt.append("Quarto: ").append(roomNumber).append(" (").append(roomType.name()).append(")\n");
173	        receipt.append("Entrada: ").append(formatDate(checkIn));
174	        receipt.append(" | Saída: ").append(formatDate(checkOut));
175	        receipt.append(" | ").append(getNights()).append(getNights() == 1 ? " diária" : " diárias").append("\n");
176	        receipt.append("Diárias: ").append(formatMoney(subtotal)).append("\n");
177	
178	        if (discount.compareTo(ZERO) > 0) {
179	            receipt.append("Desconto: ").append(formatMoney(discount)).append("\n");
180	        }
181	
182	        receipt.append("Total: ").append(formatMoney(total));
183	
184	        return receipt.toString();
185	    }
