106	             var stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
107	
108	            setReservationParameters(stmt, reservation);
109	            stmt.executeUpdate();
110	
111	            ResultSet rs = stmt.getGeneratedKeys();
112	            if (rs.next()) {
113	                reservation.setId(rs.getLong(1));
