248	        LocalDate start = month.atDay(1);
249	        LocalDate end = month.atEndOfMonth();
250	
251	        String sql = """
252	            SELECT id, room_number, guest_name, guest_email, guest_cpf,
253	                   check_in, check_out, guests, rate_plan, status, amount_paid, refund
254	            FROM reservations
255	            WHERE check_in BETWEEN ? AND ?
256	              AND (amount_paid > 0 OR refund > 0)
257	            ORDER BY check_in, id
258	            """;
259	
260	        try (Connection conn = database.getConnection();
261	             var stmt = conn.prepareStatement(sql)) {
262	
263	            stmt.setDate(1, Date.valueOf(start));
264	            stmt.setDate(2, Date.valueOf(end));
265	
266	            ResultSet rs = stmt.executeQuery();
267	            List<Reservation> reservations = new ArrayList<>();
268	            while (rs.next()) {
269	                reservations.add(mapReservation(rs));
270	            }
271	            return reservations;
272	        } catch (SQLException e) {
273	            throw new RuntimeException("Failed to find reservations", e);
274	        }
275	    }
