277	    private Reservation mapReservation(ResultSet rs) throws SQLException {
278	        return new Reservation(
279	            rs.getLong("id"),
280	            rs.getString("room_number"),
281	            rs.getString("guest_name"),
282	            rs.getString("guest_email"),
283	            rs.getString("guest_cpf"),
284	            rs.getDate("check_in").toLocalDate(),
285	            rs.getDate("check_out").toLocalDate(),
286	            rs.getInt("guests"),
287	            RatePlan.valueOf(rs.getString("rate_plan")),
288	            ReservationStatus.valueOf(rs.getString("status")),
289	            rs.getBigDecimal("amount_paid"),
290	            rs.getBigDecimal("refund")
291	        );
292	    }
293	}
